(function(root,factory){'use strict';const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;if(root)root.MotorlogSessionStore=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){'use strict';
  const temporary=['motorlog_session_token','motorlog_session_email','motorlog_admin_token','motorlog_admin_email'];
  const persistent=['motorlog_persistent_token','motorlog_persistent_email','motorlog_persistent_admin'];
  function clear(session=globalThis.sessionStorage,local=globalThis.localStorage){for(const key of temporary)session.removeItem(key);for(const key of persistent)local.removeItem(key);}
  function save({token,email,persistent:remember=false,admin=false},session=globalThis.sessionStorage,local=globalThis.localStorage){clear(session,local);session.setItem('motorlog_session_token',token);session.setItem('motorlog_session_email',email||'');if(admin){session.setItem('motorlog_admin_token',token);session.setItem('motorlog_admin_email',email||'');}if(remember){local.setItem('motorlog_persistent_token',token);local.setItem('motorlog_persistent_email',email||'');local.setItem('motorlog_persistent_admin',admin?'true':'false');}}
  function read(session=globalThis.sessionStorage,local=globalThis.localStorage){const remembered=local.getItem('motorlog_persistent_token');if(remembered)return{token:remembered,email:local.getItem('motorlog_persistent_email')||'',persistent:true,admin:local.getItem('motorlog_persistent_admin')==='true'};const token=session.getItem('motorlog_session_token')||session.getItem('motorlog_admin_token');return token?{token,email:session.getItem('motorlog_session_email')||session.getItem('motorlog_admin_email')||'',persistent:false,admin:session.getItem('motorlog_admin_token')===token}:null;}
  return{clear,save,read};
});
